-- rebuild-carnet 015 + 016 + 017 + 018 + 019 + 020 + 021 + 022 + 023 + 024 + 025 + 026 + 027 + 028 + 029 + 030 (2026-09-28): remap reader reports to the new paragraph IDs.
-- paragraph_reports is the only table keyed by paragraph ID (src/auth/init.sql).
-- Reading history / bookmarks live in each reader's localStorage and cannot be remapped here.
-- One UPDATE through a mapping table, so a chain like 0005→0006→0007 cannot double-apply.
BEGIN;
CREATE TEMP TABLE renumber_015_016_017_018_019_020_021_022_023_024_025_026_027_028_029_030 (old_id TEXT PRIMARY KEY, new_id TEXT NOT NULL) ON COMMIT DROP;
UPDATE paragraph_reports r SET paragraph_id = m.new_id FROM renumber_015_016_017_018_019_020_021_022_023_024_025_026_027_028_029_030 m WHERE r.paragraph_id = m.old_id;
COMMIT;
